package app.xenet.client;
import org.junit.*;import static org.junit.Assert.*;import org.json.*;
public class NotificationAndSettingsTest {
 @Test public void gateRejectsIdle(){assertFalse(new ReconnectGate().request("vpn","idle"));}
 @Test public void gateRejectsTests(){assertFalse(new ReconnectGate().request("real","connected"));}
 @Test public void gateRejectsRecovery(){assertFalse(new ReconnectGate().request("vpn","reconnecting"));}
 @Test public void gateCoalesces(){ReconnectGate g=new ReconnectGate();assertTrue(g.request("vpn","connected"));assertFalse(g.request("vpn","connected"));assertTrue(g.take());assertFalse(g.take());assertTrue(g.request("vpn","connected"));}
 @Test public void gateClear(){ReconnectGate g=new ReconnectGate();g.request("vpn","connected");g.clear();assertFalse(g.take());}
 @Test public void customRetryBounds(){assertEquals(5000,RetryPolicy.delayMillis(1,5,5000));assertEquals(20000,RetryPolicy.delayMillis(3,5,5000));assertEquals(30000,RetryPolicy.delayMillis(5,5,5000));assertEquals(-1,RetryPolicy.delayMillis(6,5,5000));assertEquals(-1,RetryPolicy.delayMillis(2,1,1000));}
 @Test public void settingsDefaults()throws Exception{ConnectionOptions c=ConnectionOptions.defaults();assertEquals(2000,c.pingTimeout);assertEquals(3,c.retryCount);assertEquals(1000,c.retryDelay);assertEquals("config",c.keepAlive);assertEquals("100-200",c.fragmentSize);}
 @Test public void settingsRoundTrip()throws Exception{ConnectionOptions c=new ConnectionOptions(Parser.obj("retryCount",5,"retryDelay",5000,"pingTimeout",6000,"keepAlive","on","fragmentSize","50-100","fragmentDelay","1-3"));ConnectionOptions d=new ConnectionOptions(c.json());assertEquals(c.json().toString(),d.json().toString());}
 @Test public void invalidNewSettings()throws Exception{for(String k:new String[]{"retryCount","retryDelay","pingTimeout","keepAlive","fragmentSize","fragmentDelay"})try{new ConnectionOptions(Parser.obj(k,"invalid"));fail(k);}catch(IllegalArgumentException expected){}}
 @Test public void invalidNumericSettings()throws Exception{for(String k:new String[]{"retryCount","retryDelay","pingTimeout"})try{new ConnectionOptions(Parser.obj(k,9));fail(k);}catch(IllegalArgumentException expected){}}
 JSONObject proxy()throws Exception{return Parser.obj("protocol","vless","streamSettings",Parser.obj("network","tcp","security","tls"));}
 @Test public void tcpKeepAlive()throws Exception{JSONObject p=new ConnectionOptions(Parser.obj("keepAlive","on")).apply(Parser.arr(proxy())).getJSONObject(0);JSONObject s=p.getJSONObject("streamSettings").getJSONObject("sockopt");assertEquals(45,s.getInt("tcpKeepAliveIdle"));assertEquals(15,s.getInt("tcpKeepAliveInterval"));}
 @Test public void keepAliveCopiesAndPreserves()throws Exception{JSONObject p=proxy();p.getJSONObject("streamSettings").put("sockopt",Parser.obj("mark",5));String before=p.toString();JSONObject q=new ConnectionOptions(Parser.obj("keepAlive","on")).apply(Parser.arr(p)).getJSONObject(0);assertEquals(before,p.toString());assertEquals(5,q.getJSONObject("streamSettings").getJSONObject("sockopt").getInt("mark"));}
 @Test public void skipUdpKeepalive()throws Exception{ConnectionOptions c=new ConnectionOptions(Parser.obj("keepAlive","on"));JSONObject p=proxy();p.getJSONObject("streamSettings").put("network","kcp");assertFalse(c.apply(Parser.arr(p)).getJSONObject(0).getJSONObject("streamSettings").has("sockopt"));JSONObject wg=Parser.obj("protocol","wireguard");assertFalse(c.apply(Parser.arr(wg)).getJSONObject(0).has("streamSettings"));}
 @Test public void selectedFragmentRanges()throws Exception{JSONArray a=new ConnectionOptions(Parser.obj("fragment","tlshello","fragmentSize","50-100","fragmentDelay","1-3")).apply(Parser.arr(proxy()));JSONObject f=a.getJSONObject(1).getJSONObject("settings").getJSONObject("fragment");assertEquals("50-100",f.getString("length"));assertEquals("1-3",f.getString("interval"));}
 @Test public void sectionMergePreservesOthers()throws Exception{JSONObject old=Parser.obj("appMode","include","packages",Parser.arr("a.b"),"keepAlive","on");JSONObject out=ConnectionOptions.merge(old,Parser.obj("retryCount",5));assertEquals("include",out.getString("appMode"));assertEquals("a.b",out.getJSONArray("packages").getString(0));assertEquals("on",out.getString("keepAlive"));assertEquals(5,out.getInt("retryCount"));assertFalse(old.has("retryCount"));}
 @Test public void invalidPatchRejected()throws Exception{try{ConnectionOptions.merge(null,Parser.obj("mtu",9999));fail();}catch(IllegalArgumentException expected){}}
}
